export const conservationDemand=(c,kind,amount)=>amount*(c.civic.ordinances[kind==='power'?'powerConservation':'waterConservation']?.9:1);
export function conservationReport(c){const s=c.stats,fmt=n=>(n||0).toFixed(1);return `<details><summary>Conservation · utility demand</summary><p>Power demand: ${fmt(s.powerDemand)} units; conservation saves ${fmt(s.powerConserved)}. Water demand: ${fmt(s.waterDemand)} units; conservation saves ${fmt(s.waterConserved)}.</p><p>Each enabled policy reduces its resource demand by 10%. These totals include unserved zones; supply still has to reach each network. Conservation cannot repair a disconnected line or pipe. Enable or repeal the policies in Civic services.</p></details>`;}
